import React, { useEffect, useState } from 'react';

export default function AchievementsPanel({ token, me = {}, role = 'user', onViewNgo, setMsg }) {
  const [achievements, setAchievements] = useState(null);
  const [badges, setBadges] = useState([]);

  // Badge rules: type = 'volunteer' or 'donate'
  const badgeRules = {
    user: [
      { title: "Bronze Volunteer", points: 50, type: "volunteer", icon: "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105" },
      { title: "Silver Volunteer", points: 150, type: "volunteer", icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120" },
      { title: "Gold Volunteer", points: 300, type: "volunteer", icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121" },
    ],
    NGO: [
      { title: "Silver Donor", points: 100, type: "donate", icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120" },
      { title: "Gold Donor", points: 250, type: "donate", icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121" },
      { title: "Platinum Donor", points: 500, type: "donate", icon: "https://tse3.mm.bing.net/th/id/OIP.Imd7GlakFy5b_od5xomrDAHaHa?pid=Api&P=0&h=180" },
    ]
  };

  // Load achievements and badges from backend
  useEffect(() => {
    if (!token) return;

    const apiBase = process.env.REACT_APP_API || 'http://localhost:4000';
    const userUrl = role === 'NGO' ? `${apiBase}/api/ngo/achievements` : `${apiBase}/api/actions/achievements`;

    fetch(userUrl, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { 
        setAchievements(d); 
        setBadges(d?.badges || []); 
      })
      .catch(err => { console.error('Achievements load error', err); setAchievements({ badges: [] }); });

    fetch(`${apiBase}/api/actions/user-badges`, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { if (d?.badges) setBadges(d.badges); })
      .catch(() => {});
  }, [token, role]);

  // Function to handle points increase on action
  const handleAction = (type, pointsEarned) => {
    // Update user points
    me.points = (me.points || 0) + pointsEarned;

    // Check badges for this action type
    const newBadges = badgeRules[role]
      .filter(b => b.type === type) // only badges of this action type
      .filter(b => me.points >= b.points) // check if points threshold met
      .map(b => ({ ...b, description: `Earned at ${b.points} points` }));

    // Merge with existing badges without duplicates
    const merged = [...new Map([...badges, ...newBadges].map(b => [b.title, b])).values()];
    setBadges(merged);
  };

  return (
    <div style={{ width: 320, flexShrink: 0 }}>
      <h3 style={{ marginBottom: 12 }}>Achievements</h3>

      <div style={{
        background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
        padding: 18,
        borderRadius: 12,
        color: '#fff',
        textAlign: 'center',
        boxShadow: '0 8px 30px rgba(2,6,23,0.08)'
      }}>
        <div style={{ fontSize: 42, fontWeight: 800 }}>{me?.points || 0}</div>
        <div style={{ opacity: 0.9, marginTop: 6 }}>POINTS</div>
      </div>

      <div style={{ marginTop: 14 }}>
        <h4 style={{ marginBottom: 8 }}>Badges</h4>

        {!achievements && (
          <div style={{ fontSize: 13, color: '#666' }}>Loading badges...</div>
        )}

        {achievements && badges.length === 0 && (
          <div style={{ padding: 14, borderRadius: 10, background: '#fff', color: '#666', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>No badges yet — participate to earn rewards.</div>
        )}

        {badges.length > 0 && (
          <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(2,1fr)",
            gap: 10,
            marginTop: 10,
          }}>
            {badges.map((b, i) => (
              <div key={b.title || i} style={{
                background: "#fff",
                padding: 10,
                borderRadius: 10,
                boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
                border: "1px solid #f1f5f9",
                textAlign: "center",
              }}>
                {b.icon && <img src={b.icon} alt={b.title} style={{ width: 45, height: 45, marginBottom: 6, objectFit: "contain" }} />}
                <div style={{ fontWeight: 700, fontSize: 14 }}>{b.title}</div>
                <div style={{ fontSize: 12, color: "#555" }}>{b.description}</div>
              </div>
            ))}
          </div>
        )}
      </div>

      {onViewNgo && (
        <div style={{ marginTop: 18 }}>
          <button onClick={() => onViewNgo()} style={{ width: '100%', padding: '10px 12px', borderRadius: 10, background: '#2563eb', color: '#fff', border: 0, cursor: 'pointer' }}>View Hosting NGOs</button>
        </div>
      )}

      {/* TEST BUTTONS (simulate action) */}
      <div style={{ marginTop: 20, display: "flex", gap: 10 }}>
        <button onClick={() => handleAction('volunteer', 60)} style={{ flex: 1, padding: 10 }}>Volunteer +60 pts</button>
        <button onClick={() => handleAction('donate', 120)} style={{ flex: 1, padding: 10 }}>Donate +120 pts</button>
      </div>
    </div>
  );
}
